import * as fabric from 'fabric';
import { v4 as uuid } from 'uuid';
import { fitTextToRect, registerFabricClass, resolveFromObject } from '../../../../canvas';
import { FromPort, PortObject } from '../../../../canvas/objects';
import LogicNode from './LogicNode';

const getPortShift = (options: any) => Math.max(0, ((options.configuration?.routes?.length ?? 0) * 80 - 240) / 2);

class SwitchNode extends LogicNode {
	static type = 'SwitchNode';

	portWidth = 80;
	portHeight = 40;
	defaultRouteLength = 3;
	declare configuration: { routes: string[] } & Record<string, any>;
	declare ports: PortObject[];

	constructor(options: any = {}) {
		const nextOptions = { ...options };
		if (nextOptions.__baseLeft == null) {
			nextOptions.__baseLeft = nextOptions.left ?? 0;
		}
		const shift = getPortShift(nextOptions);
		super({
			...nextOptions,
			left: nextOptions.__baseLeft + shift,
			nodeClazz: nextOptions.nodeClazz ?? SwitchNode.type,
		});
	}

	createFromPort(x: number, y: number) {
		const routeFill = (this as any).routeFill || '#272e38';
		const routeStroke = (this as any).routeStroke || '#5f646b';
		const routeTextColor = (this as any).routeTextColor || '#fff';
		const isEven = this.configuration.routes.length % 2 === 0;
		const calcOdd = (port: PortObject, i: number) => {
			const centerIndex = Math.ceil(this.configuration.routes.length / 2);
			const index = i + 1;
			let left;
			let leftDiff;
			const width = port.width ?? 0;
			if (centerIndex === index) {
				left = x;
			} else if (centerIndex > index) {
				left = x - width * (centerIndex - index);
				leftDiff = -width * (centerIndex - index);
			} else {
				left = x + width * (index - centerIndex);
				leftDiff = width * (index - centerIndex);
			}
			return {
				left,
				leftDiff,
			};
		};
		const calcEven = (port: PortObject, i: number) => {
			const centerIndex = this.configuration.routes.length / 2;
			const index = i + 1;
			let left;
			let leftDiff;
			const width = port.width ?? 0;
			if (centerIndex >= index) {
				left = x - width / 2 - width * (centerIndex - index);
				leftDiff = -(width / 2) - width * (centerIndex - index);
			} else {
				left = x - width / 2 + width * (index - centerIndex);
				leftDiff = -(width / 2) + width * (index - centerIndex);
			}
			return {
				left,
				leftDiff,
			};
		};
		const canvas = document.createElement('canvas');
		const context = canvas.getContext('2d')!;
		this.ports = this.configuration.routes.map((outPort: string, i: number) => {
			const rect = new fabric.Rect({
				width: this.portWidth,
				height: this.portHeight,
				originX: 'center',
				originY: 'center',
				fill: routeFill,
				// @ts-ignore
				originFill: routeFill,
				stroke: routeStroke,
				rx: 12,
				ry: 12,
			});
			const { text, fontSize } = fitTextToRect(context, outPort, this.fontSize, this.fontFamily, 72, 32);
			const label = new fabric.Text(text, {
				fontSize,
				fontFamily: 'Noto Sans',
				fontWeight: 400,
				fill: routeTextColor,
				originX: 'center',
				originY: 'center',
			});
			let coords;
			if (isEven) {
				coords = calcEven(rect, i);
			} else {
				coords = calcOdd(rect, i);
			}
			const portLabel = new fabric.Group([rect, label], {
				// @ts-ignore
				id: outPort,
				width: this.portWidth,
				height: this.portHeight,
				rx: 7,
				ry: 7,
				left: coords.left,
				top: y + 20,
				leftDiff: coords.leftDiff,
				topDiff: 20,
				fill: routeFill,
				originX: 'center',
				originY: 'center',
			});
			return portLabel as unknown as PortObject;
		});
		this.ports.forEach((port: PortObject) => {
			this.add(port);
			port.setCoords();
		});
		this.fromPort = this.ports.map((port: PortObject, i: number) => {
			let coords;
			if (isEven) {
				coords = calcEven(port, i);
			} else {
				coords = calcOdd(port, i);
			}
			const height = port.height ?? 0;
			const top = y + height;
			port.fromPort = new FromPort({
				id: port.id,
				left: coords.left,
				top,
				leftDiff: coords.leftDiff,
				...this.fromPortOption(),
				radius: 12,
			});
			port.fromPort.setPosition(coords.left, top);
			return port.fromPort;
		});
		return this.fromPort;
	}

	duplicate(): any {
		const options = this.toObject();
		options.id = uuid();
		options.name = `${options.name}_clone`;
		options.__baseLeft = (options.left ?? 0) - getPortShift(options);
		return new SwitchNode(options);
	}

	toObject(propertiesToInclude: any[] = []) {
		const options = super.toObject(propertiesToInclude);
		options.top = this.rect.getCenterPoint().y;
		return options;
	}

	static fromObject(options: any, _abortable?: any) {
		return resolveFromObject(new SwitchNode({ ...options, __baseLeft: (options.left ?? 0) - getPortShift(options) })) as Promise<any>;
	}
}

registerFabricClass('SwitchNode', SwitchNode);

export default SwitchNode;
