import { FormInstance, message, Popconfirm } from 'antd';
import i18next from 'i18next';
import { debounce } from 'lodash-es';
import React from 'react';
import { FabricObject } from '../../canvas';
import Canvas, { CanvasInstance } from '../../canvas/Canvas';
import { CommonButton } from '../../components/common';
import {
	EditorActivityRail,
	EditorStatusBar,
	resolveInspectorMode,
	summarizeWorkflow,
} from '../../components/editor';
import { Content } from '../../components/layout';
import Icon from '../../components/icon/Icon';
import {
	applyWorkflowCanvasTheme,
	EditorThemeContext,
	getEditorCanvasTheme,
	getWorkflowCanvasTheme,
	type EditorTheme,
} from '../../theme';
import { getNode } from './configuration/NodeConfiguration';
import { OUT_PORT_TYPE } from './constant/constants';
import NodeConfigurationError from './error/NodeConfigurationError';
import Links from './link';
import Nodes from './node';
import WorkflowConfigurations from './WorkflowConfigurations';
import WorkflowDiagnosticsDock, { type WorkflowDockTab } from './WorkflowDiagnosticsDock';
import WorkflowItems from './WorkflowItems';
import WorkflowNodeConfigurations from './WorkflowNodeConfigurations';
import WorkflowTitle from './WorkflowTitle';
import WorkflowToolbar from './WorkflowToolbar';

interface IState {
	loading: boolean;
	zoomRatio: number;
	workflow: any;
	selectedItem: any;
	descriptors: any;
	editing: boolean;
	activeActivity: string;
	dockOpen: boolean;
	dockTab: WorkflowDockTab;
}

class WorkflowEditor extends React.Component {
	static contextType = EditorThemeContext;
	declare context: React.ContextType<typeof EditorThemeContext>;

	private appliedTheme: EditorTheme | null = null;

	state: IState = {
		loading: true,
		zoomRatio: 1,
		workflow: {},
		selectedItem: null,
		descriptors: {},
		editing: false,
		activeActivity: 'build',
		dockOpen: true,
		dockTab: 'overview',
	};

	canvasRef!: CanvasInstance;
	nodeConfigurationRef = React.createRef<FormInstance>();
	container: HTMLDivElement | null = null;

	componentDidMount() {
		this.appliedTheme = this.context.theme;
		import('./Descriptors.json').then(descriptors => {
			this.setState({ descriptors: descriptors.default }, () => this.hideLoading());
		});
	}

	componentDidUpdate() {
		if (this.appliedTheme === this.context.theme || !this.canvasRef?.handler) {
			return;
		}
		this.appliedTheme = this.context.theme;
		const canvasTheme = getEditorCanvasTheme(this.context.theme);
		const nodes = Nodes(this.state.descriptors, this.context.theme);
		const links = Links(this.context.theme);
		this.canvasRef.canvas.selectionColor = canvasTheme.selectionColor;
		this.canvasRef.handler.setFabricObjects({ ...nodes, ...links });
		this.canvasRef.handler.gridHandler.initialize();
		applyWorkflowCanvasTheme(this.canvasRef.handler.getObjects(), this.context.theme);
		this.canvasRef.canvas.requestRenderAll();
	}

	canvasHandlers = {
		onZoom: (zoom: number) => {
			this.setState({ zoomRatio: zoom });
		},
		onAdd: (target: FabricObject & Record<string, any>) => {
			if (!this.state.editing) {
				this.changeEditing(true);
			}
			if (this.canvasRef?.handler.isActiveSelection(target)) {
				this.canvasHandlers.onSelect(null);
				return;
			}
			if (target.superType === 'node') {
				this.canvasRef.handler.nodeHandler.highlightingNode(target as any);
				this.canvasRef.handler.select(target as any);
			}
		},
		onSelect: (target: any) => {
			const currentSelectedItem = this.state.selectedItem;
			this.nodeConfigurationRef.current
				?.validateFields()
				.then(() => {
					if (currentSelectedItem) {
						currentSelectedItem.setErrors(
							!!(currentSelectedItem.errors && currentSelectedItem.errors.length),
						);
					}
				})
				.catch((error: { outOfDate?: boolean }) => {
					if (error.outOfDate) {
						return;
					}
					currentSelectedItem?.setErrors(true);
				});
			if (
				target &&
				target.id &&
				target.id !== 'workarea' &&
				!this.canvasRef?.handler.isActiveSelection(target) &&
				target.superType !== 'link' &&
				target.superType !== 'port'
			) {
				this.setState({ selectedItem: target });
				return;
			}
			this.setState({ selectedItem: null }, () => {
				this.canvasRef.handler.nodeHandler.deselect();
			});
		},
		onRemove: () => {
			if (!this.state.editing) {
				this.changeEditing(true);
			}
		},
		onModified: () => {
			if (!this.state.editing) {
				this.changeEditing(true);
			}
		},
		onTransaction: () => {
			applyWorkflowCanvasTheme(this.canvasRef.handler.getObjects(), this.context.theme);
			this.canvasRef.canvas.requestRenderAll();
			this.forceUpdate();
		},
	};

	handlers = {
		onImport: (files: FileList | null) => {
			if (files?.length) {
				this.showLoading();
				const reader = new FileReader();
				reader.onload = async (e: ProgressEvent<FileReader>) => {
					try {
						const result = JSON.parse(String(e.target?.result || '{}')) as any;
						if (!result || !Array.isArray(result.nodes) || !Array.isArray(result.links) || !result.properties) {
							throw new Error('Invalid workflow file');
						}
						const { viewportTransform } = result.properties;
						if (viewportTransform && (!Array.isArray(viewportTransform) || viewportTransform.length !== 6 ||
							!viewportTransform.every((value: unknown) => typeof value === 'number' && Number.isFinite(value)))) {
							throw new Error('Invalid workflow viewport');
						}
						const nodes = (result.nodes || []).map((node: any) => {
							if (!node || typeof node.nodeClazz !== 'string' || !node.id ||
								!this.canvasRef.handler.fabricObjects?.[getNode(node.nodeClazz)]) {
								throw new Error('Invalid workflow node');
							}
							const prepared = this.canvasRef.handler.fabricObjects[getNode(node.nodeClazz)].create({
								...node,
								left: node.properties ? node.properties.left : 0,
								top: node.properties ? node.properties.top : 0,
							});
							return prepared.toObject(this.canvasRef.handler.propertiesToInclude);
						});
						const links = (result.links || []).map((link: any) => {
							if (!link || typeof link.fromPort !== 'string' ||
								!nodes.some((node: any) => node.id === link.fromNode) ||
								!nodes.some((node: any) => node.id === link.toNode)) {
								throw new Error('Invalid workflow connection');
							}
							return {
								fromNodeId: link.fromNode,
								fromPortId: link.fromPort,
								toNodeId: link.toNode,
								type: 'link',
								superType: 'link',
								left: link.properties ? link.properties.left : 0,
								top: link.properties ? link.properties.top : 0,
							};
						});
						const objects = nodes.concat(links) as any[];
						// Replay restores the previous canvas if node, port or link construction fails.
						await this.canvasRef.handler.transactionHandler.replay({ type: 'add', json: JSON.stringify(objects) }, false);
						this.canvasRef.handler.getObjects().forEach(object => {
							if (object.superType === 'node') {
								this.canvasRef.handler.gridHandler.setCoords(object);
							}
						});
						this.canvasRef.handler.transactionHandler.setDefaultObjects();
						if (viewportTransform) {
							this.canvasRef.canvas.setViewportTransform(viewportTransform);
						}
						this.setState({ workflow: result, editing: false, selectedItem: null });
						this.hideLoading();
						this.canvasRef.canvas.setZoom(this.state.zoomRatio);
					} catch (error: any) {
						message.error(error?.message || 'Failed to import workflow');
						this.hideLoading();
					}
				};
				reader.readAsText(files[0]);
			}
		},
		onUpload: () => {
			const inputEl = document.createElement('input');
			inputEl.accept = '.json';
			inputEl.type = 'file';
			inputEl.hidden = true;
			inputEl.onchange = (e: any) => {
				this.handlers.onImport(e.target.files);
			};
			document.body.appendChild(inputEl); // required for firefox
			inputEl.click();
			inputEl.remove();
		},
		onDownload: () => {
			this.showLoading();
			const workflow = this.handlers.exportJsonCode();
			if (workflow) {
				const anchorEl = document.createElement('a');
				anchorEl.href = `data:text/json;charset=utf-8,${encodeURIComponent(
					JSON.stringify(workflow, null, '\t'),
				)}`;
				anchorEl.download = `${workflow.name}.json`;
				document.body.appendChild(anchorEl); // required for firefox
				anchorEl.click();
				anchorEl.remove();
				this.changeEditing(false);
				this.hideLoading();
			}
		},
		exportJsonCode: () => {
			const workflow = Object.assign({}, this.state.workflow);
			const nodes: any[] = [];
			const links: any[] = [];
			try {
				this.canvasRef.handler.exportJSON().forEach((obj: any) => {
					if (obj.superType === 'node') {
						if (obj.errors) {
							throw new NodeConfigurationError(
								i18next.t('workflow.validate-fields-error'),
								obj.id,
								obj.name,
							);
						}
						const node = {
							id: obj.id,
							name: obj.name,
							description: obj.description,
							nodeClazz: obj.nodeClazz,
							configuration: obj.configuration,
							properties: {
								left: obj.left || 0,
								top: obj.top || 0,
								icon: obj.icon,
							},
						};
						nodes.push(node);
					} else if (obj.superType === 'link') {
						const link = {
							fromNode: obj.fromNode.id,
							fromPort: obj.fromPort.id,
							toNode: obj.toNode.id,
							properties: {
								left: obj.left || 0,
								top: obj.top || 0,
							},
						};
						links.push(link);
					}
				});
				workflow.nodes = nodes;
				workflow.links = links;
				const properties = {
					viewportTransform: this.canvasRef.canvas.viewportTransform,
				};
				workflow.properties = properties;
				return workflow;
			} catch (error: any) {
				console.error(`[ERROR] ${this.constructor.name} exportJsonCode()`, error);
				if (error?.nodeId) {
					this.canvasRef.handler.selectById(error.nodeId);
				}
				message.error(error?.message || 'Failed to export workflow');
				this.hideLoading();
			}
		},
		onChange: debounce((selectedItem: any, changedValues: any, allValues: any) => {
			if (!this.state.editing) {
				this.changeEditing(true);
			}
			if (changedValues.workflow) {
				const workflow = Object.assign({}, this.state.workflow, changedValues.workflow);
				this.setState({
					workflow,
				});
			} else {
				setTimeout(async () => {
					const errors = this.nodeConfigurationRef.current?.getFieldsError();
					if (Object.values(errors).filter(error => error.errors?.length).length) {
						selectedItem?.setErrors(true);
					} else {
						selectedItem?.setErrors(false);
					}
					this.canvasRef.handler.transactionHandler.save('configuration');
					this.canvasRef.canvas.renderAll();
				}, 0);
				const configuration = Object.assign({}, selectedItem?.configuration, changedValues.configuration);
				this.canvasRef.handler.setObject({
					configuration,
					name: allValues.name,
					description: allValues.description,
				});
				selectedItem.setName(allValues.name);
				if (selectedItem.descriptor.outPortType === OUT_PORT_TYPE.DYNAMIC) {
					this.canvasRef.handler.portHandler.recreate(selectedItem);
				}
				this.canvasRef.handler.transactionHandler.save('configuration');
			}
		}, 200),
		onActivityChange: (activeActivity: string) => {
			if (activeActivity === 'diagnostics') {
				this.setState({ activeActivity, dockOpen: true, dockTab: 'validation' });
				return;
			}
			if (activeActivity === 'history') {
				this.setState({ activeActivity, dockOpen: true, dockTab: 'history' });
				return;
			}
			this.setState({ activeActivity, dockOpen: false });
		},
	};

	showLoading = () => {
		this.setState({
			loading: true,
		});
	};

	hideLoading = () => {
		this.setState({
			loading: false,
		});
	};

	changeEditing = (editing: boolean) => {
		this.setState({
			editing,
		});
	};

	render() {
		const canvasTheme = getEditorCanvasTheme(this.context.theme);
		const workflowCanvasTheme = getWorkflowCanvasTheme(this.context.theme);
		const {
			zoomRatio,
			workflow,
			selectedItem,
			descriptors,
			loading,
			editing,
			activeActivity,
			dockOpen,
			dockTab,
		} = this.state;
		const { onChange, onDownload, onUpload } = this.handlers;
		const { onZoom, onAdd, onSelect, onRemove, onModified } = this.canvasHandlers;
		const nodes = Nodes(descriptors, this.context.theme);
		const links = Links(this.context.theme);
		const canvasObjects = this.canvasRef?.handler.getObjects() || [];
		const summary = summarizeWorkflow(canvasObjects);
		const transactionHandler = this.canvasRef?.handler.transactionHandler;
		const inspectorMode = resolveInspectorMode(selectedItem);
		const action = (
			<React.Fragment>
				<CommonButton
					className="rde-action-btn"
					icon="file-download"
					disabled={!editing}
					tooltipTitle={i18next.t('action.download')}
					onClick={onDownload}
					tooltipPlacement="bottomRight"
				>
					Export
				</CommonButton>
				{editing ? (
					<Popconfirm
						title={i18next.t('workflow.workflow-editing-confirm')}
						okText={i18next.t('action.ok')}
						cancelText={i18next.t('action.cancel')}
						onConfirm={onUpload}
						placement="bottomRight"
					>
						<CommonButton
							className="rde-action-btn"
							shape="circle"
							icon="file-upload"
							tooltipTitle={i18next.t('action.upload')}
							tooltipPlacement="bottomRight"
						/>
					</Popconfirm>
				) : (
					<CommonButton
						className="rde-action-btn"
						shape="circle"
						icon="file-upload"
						tooltipTitle={i18next.t('action.upload')}
						tooltipPlacement="bottomRight"
						onClick={onUpload}
					/>
				)}
			</React.Fragment>
		);
		const titleContent = (
			<React.Fragment>
				<span className="rde-editor-breadcrumb-section">Workflows</span>
				<span className="rde-editor-breadcrumb-divider">/</span>
				<strong>{workflow.name || i18next.t('workflow.workflow-editor')}</strong>
				<span className={`rde-editor-save-state ${editing ? 'editing' : 'saved'}`}>
					{editing ? 'Unsaved changes' : 'Saved'}
				</span>
			</React.Fragment>
		);
		const title = <WorkflowTitle title={titleContent} action={action} />;
		const content = (
			<div className="rde-editor rde-operator-editor rde-workflow-editor">
				<EditorActivityRail
					label="Workflow workspace"
					activeKey={activeActivity}
					onChange={this.handlers.onActivityChange}
					items={[
						{ key: 'build', label: 'Build', icon: 'project-diagram' },
						{ key: 'diagnostics', label: 'Validation', icon: 'tasks', badge: summary.errorCount },
						{ key: 'history', label: 'History', icon: 'history' },
					]}
				/>
				<WorkflowItems
					instance={this.canvasRef}
					selectedItem={this.state.selectedItem}
					descriptors={descriptors}
				/>
				<section
					ref={(c: HTMLDivElement | null) => {
						this.container = c;
					}}
					className="rde-editor-workspace"
				>
					<div className="rde-editor-canvas">
						<Canvas
							ref={(c: CanvasInstance | null) => {
								if (c) {
									this.canvasRef = c;
								}
							}}
							className="rde-canvas"
							canvasOption={{
								backgroundColor: canvasTheme.backgroundColor,
								selectionColor: canvasTheme.selectionColor,
							}}
							fabricObjects={{ ...nodes, ...links } as any}
							workareaOption={{
								width: 0,
								height: 0,
							}}
							gridOption={{
								enabled: true,
								grid: 20,
								snapToGrid: true,
								type: 'dot',
								dotColor: canvasTheme.dotColor,
							}}
							activeSelectionOption={{
								hasControls: false,
								hasBorders: false,
								perPixelTargetFind: true,
							}}
							linkOption={{ stroke: workflowCanvasTheme.linkColor, strokeWidth: 2 }}
							minZoom={30}
							maxZoom={200}
							onZoom={onZoom}
							onSelect={onSelect}
							onAdd={onAdd}
							onRemove={onRemove}
							onModified={onModified}
							onTransaction={this.canvasHandlers.onTransaction}
							onClick={(_canvas: any, target: any, subTarget: any) => {
								if (subTarget && target.ports?.length) {
									const spinner = target.ports.find((p: any) => p.type === 'spinner');
									spinner?.setVisibility(true);
									setTimeout(() => {
										spinner?.setVisibility(false);
									}, 5000);
								}
							}}
							canvasActions={{ move: false, transaction: true, clipboard: true }}
							guidelineOption={{ enabled: false }}
							shouldHighlightPathOnSelect={true}
						/>
					</div>
					<WorkflowDiagnosticsDock
						activeTab={dockTab}
						canRedo={Boolean(transactionHandler?.canRedo())}
						canUndo={Boolean(transactionHandler?.canUndo())}
						editing={editing}
						open={dockOpen}
						summary={summary}
						onChangeTab={nextTab =>
							this.setState({ dockTab: nextTab, dockOpen: true, activeActivity: 'diagnostics' })
						}
						onRedo={() => transactionHandler?.redo()}
						onToggle={() => this.setState({ dockOpen: !dockOpen })}
						onUndo={() => transactionHandler?.undo()}
					/>
					<EditorStatusBar
						left={<WorkflowToolbar instance={this.canvasRef} zoomRatio={zoomRatio} />}
						center={
							<span>
								{summary.nodeCount} nodes · {summary.linkCount} connections
							</span>
						}
						right={
							<span className={summary.errorCount ? 'rde-status-issue' : 'rde-status-ok'}>
								<Icon name={summary.errorCount ? 'exclamation-circle' : 'check-circle'} />
								{summary.errorCount ? `${summary.errorCount} issues` : 'No issues'}
							</span>
						}
					/>
				</section>
				<aside className="rde-editor-inspector">
					{inspectorMode === 'node' ? (
						<WorkflowNodeConfigurations
							ref={this.nodeConfigurationRef}
							selectedItem={selectedItem}
							workflow={workflow}
							canvasRef={this.canvasRef}
							descriptors={descriptors}
							onChange={onChange}
						/>
					) : (
						<WorkflowConfigurations
							workflow={workflow}
							selectedItem={selectedItem}
							canvasRef={this.canvasRef}
							onChange={onChange}
						/>
					)}
				</aside>
			</div>
		);
		return <Content title={title} content={content} loading={loading} className="" />;
	}
}

export default WorkflowEditor;
